/**
 * A class that is an Adapter in order to allow for the use of existing {@link DynamicTableColumn}s
 * when the actual row type of the table is not the same as the row type that the
 * {@link DynamicTableColumn} supports.
 *
 * @param <ROW_TYPE> The table's actual row type
 * @param <EXPECTED_ROW_TYPE> The row type expected by the given {@link DynamicTableColumn}
 * @param <COLUMN_TYPE> The column type provided by the given {@link DynamicTableColumn}
 * @param <DATA_SOURCE> the type of the data for each column; can be Object for columns that do not
 *            have a data source
 */
public class MappedTableColumn<ROW_TYPE, EXPECTED_ROW_TYPE, COLUMN_TYPE, DATA_SOURCE> : AbstractDynamicTableColumn<ROW_TYPE, COLUMN_TYPE, DATA_SOURCE> {

	protected TableRowMapper<ROW_TYPE, EXPECTED_ROW_TYPE, DATA_SOURCE> mapper;
	protected DynamicTableColumn<EXPECTED_ROW_TYPE, COLUMN_TYPE, DATA_SOURCE> tableColumn;

	protected MappedTableColumn(TableRowMapper<ROW_TYPE, EXPECTED_ROW_TYPE, DATA_SOURCE> mapper,
			DynamicTableColumn<EXPECTED_ROW_TYPE, COLUMN_TYPE, DATA_SOURCE> tableColumn) : this(mapper, tableColumn, tableColumn.getUniqueIdentifier())
    {
	}

	protected MappedTableColumn(TableRowMapper<ROW_TYPE, EXPECTED_ROW_TYPE, DATA_SOURCE> mapper,
			DynamicTableColumn<EXPECTED_ROW_TYPE, COLUMN_TYPE, DATA_SOURCE> tableColumn,
			string uniqueIdentifier) : base(uniqueIdentifier)
    {
		this.mapper = mapper;
		this.tableColumn = tableColumn;
	}

	/**
	 * Returns the class of the column that this mapper wraps
	 * 
	 * @return the class of the column that this mapper wraps
	 */
	public Class<object> getMappedColumnClass() {
		if (tableColumn is MappedTableColumn) {
