		return tableColumn.getColumnDisplayName(settings);
	}

	/* @Override */
	public string getColumnDescription() {
		return tableColumn.getColumnDescription();
	}

	/* @Override */
	public string getColumnName() {
		return tableColumn.getColumnName();
	}

